/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args    _args)
{
    NumberSequenceReference          numSeqRef;
    NumberSequenceTable              numSeqTable;
    NumberSequenceDatatype           numSeqDT;
    Dialog                           dialog = new Dialog();
    DialogField                      dlgNumSegNum = dialog.addField(extendedTypeStr(Name));
    Name                             numSeqName;

    if (dialog.run())
    {
        numSeqName =dlgNumSegNum.value();
        select firstonly numSeqTable
            where numSeqTable.NumberSequence == numSeqName;

        Info(strFmt('Nächste nummer %1',numSeqTable.NextRec));

        delete_from numSeqRef
            where numSeqRef.NumberSequenceId == numSeqTable.RecId;

        delete_from numSeqTable
            where numSeqTable.NumberSequence == numSeqName;

        delete_from numSeqDT
            where numSeqDT.DatatypeId == extendedTypeNum(KCS_KBVBuildingProjectID);




        AVANumberSeqBPInitJob::main(_args);
    }
}
